        results.append({"id": doc.id, "document": doc.to_dict()})
    return results

from google.cloud import firestore
from database_client import get_firestore_client

def conditional_update(doc_id: str, collection_name: str, updates: dict, condition_field: str, condition_value: any, config: dict = None):
    config = config or {}
    client = get_firestore_client(project_id=config["project_id"])
    doc_ref = client.collection(collection_name).document(doc_id)

    # Using a transaction to ensure atomicity for conditional update
    @firestore.transactional
    def update_in_transaction(transaction, doc_ref, updates, condition_field, condition_value):
        snapshot = doc_ref.get(transaction=transaction)
        if not snapshot.exists:
            raise ValueError(f"Document {doc_id} does not exist.")

        current_data = snapshot.to_dict()
        if current_data.get(condition_field) == condition_value:
            transaction.update(doc_ref, updates)
            return True
        else:
            return False

    transaction = client.transaction()
    try:
        success = update_in_transaction(transaction, doc_ref, updates, condition_field, condition_value)
        return {"id": doc_id, "success": success}
    except ValueError as e:
        return {"id": doc_id, "success": False, "error": str(e)}

import os
import google.generativeai as genai

def record_summary(text_content: str, config: dict = None):
    config = config or {}
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY", config.get("google_api_key")))
    model = genai.GenerativeModel('gemini-pro')
    prompt = f"Summarize the following text:\n\n{text_content}"
    response = model.generate_content(prompt)
    return {"summary": response.text}

import os
from google.cloud import language_v2

def record_text_safety(text_content: str, config: dict = None):
    config = config or {}
    client = language_v2.LanguageServiceClient()
    document = language_v2.Document(content=text_content, type_=language_v2.Document.Type.PLAIN_TEXT)

    # Available categories are https://cloud.google.com/natural-language/docs/moderating-text
    response = client.moderate_text(document=document)

    safety_attributes = []
    for category_filter in response.moderation_categories:
        safety_attributes.append({
            "category": category_filter.name,
            "score": category_filter.score,
            "unsafe": category_filter.score > 0.5 # Example threshold for unsafe
        })

    return {"safety_attributes": safety_attributes}

import os
from google.cloud import translate

def record_translate(text_content: str, target_language: str, project_id: str, config: dict = None):
    config = config or {}
    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_content],
            "target_language_code": target_language,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append({
            "translated_text": translation.translated_text,
            "detected_language_code": translation.detected_language_code
        })
    return {"translations": translations}

import os
import boto3

def record_export_archive(file_content: bytes, bucket_name: str, object_key: str, config: dict = None):
    config = config or {}
    s3_client = boto3.client(
        's3',
        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID", config.get("aws_access_key_id")),
        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY", config.get("aws_secret_access_key")),
        region_name=os.environ.get("AWS_REGION", config.get("aws_region", "us-east-1"))
    )
    s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=file_content)
    return {"bucket": bucket_name, "key": object_key, "status": "archived"}
